      3'd2: y = a & b;
      3'd3: y = a | b;
      3'd4: y = a ^ b;
      3'd5: begin
        y = a << 1;
        carry = a[WIDTH-1];
      end
      3'd6: begin
        y = a >> 1;
        carry = a[0];
      end
      3'd7: y = (a < b) ? 1'b1 : 1'b0;
      default: y = 0;
    endcase
  end

  assign zero = (y == 0);
endmodule

